using System;using System.Linq;using UnityEngine;
namespace LostRealmsOW {
 public sealed class OpenWorldHorseCoat:MonoBehaviour {void Start(){var a=GetComponent<OpenWorldAnimalInteraction>();if(a&&a.Horse)OpenWorldHorseProgression.ApplyCoat(a);}}
 public sealed class OpenWorldHorseProgression:MonoBehaviour {
  public struct BreedSpec {public string Name;public int Price,Stamina,Trials;public float Speed;public Color Coat;public BreedSpec(string name,int price,float speed,int stamina,int trials,Color coat){Name=name;Price=price;Speed=speed;Stamina=stamina;Trials=trials;Coat=coat;}}
  public static readonly BreedSpec[] Breeds={new BreedSpec("Bay Road Horse",350,8.2f,100,8,new Color(.75f,.48f,.30f)),new BreedSpec("Midnight Courser",900,11f,80,12,new Color(.24f,.27f,.32f)),new BreedSpec("Golden Highlander",700,9.2f,150,10,new Color(1.3f,1.12f,.72f))};
  static OpenWorldHorseProgression instance;public static OpenWorldHorseProgression Instance=>instance?instance:(instance=FindAnyObjectByType<OpenWorldHorseProgression>());public static readonly Vector3 Stable=new Vector3(-36,0,8);
  public OpenWorldAnimalInteraction Target;public int Successes,Mistakes,Direction;public float Deadline;float retryAt;GameObject stall;OpenWorldAnimalInteraction personal;OpenWorldWildlife restrained;
  OpenWorldManager GM=>OpenWorldManager.I?OpenWorldManager.I:FindAnyObjectByType<OpenWorldManager>();
  public int Skill=>GM?Mathf.Min(4,GM.CollectedWorldIds.Count(f=>f.StartsWith("horse-skill:"))):0;
  public int Required=>Target?Mathf.Max(5,Breeds[Target.Breed].Trials-Skill):0;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){new GameObject("Horse ownership and stables").AddComponent<OpenWorldHorseProgression>();}
  void Awake(){instance=this;}
  public static int BreedFor(string id){unchecked{uint h=2166136261;foreach(char c in id??"")h=(h^c)*16777619;return(int)(h%3);}}
  public static void Begin(OpenWorldAnimalInteraction horse){var p=Instance;if(!p||p.Target||Time.unscaledTime<p.retryAt||!horse||horse.Owned)return;p.Target=horse;p.Successes=p.Mistakes=0;p.restrained=horse.GetComponent<OpenWorldWildlife>();if(p.restrained)p.restrained.enabled=false;p.Cue();}
  void Cue(){var motion=Target.GetComponentInChildren<OpenWorldImportedModel>();if(motion&&motion.Buck){motion.State="buck";motion.RestartVersion++;}Direction=UnityEngine.Random.value<.5f?-1:1;Deadline=Time.unscaledTime+1.05f+Skill*.18f;GM?.ShowBanner("COUNTERBALANCE "+(Direction<0?"LEFT":"RIGHT")+" • "+Successes+"/"+Required);}
  public void Counter(int side){if(!Target)return;if(side==Direction&&Time.unscaledTime<=Deadline){Successes++;if(Successes>=Required){int breed=Target.Breed;var at=Target.transform.position;var old=Target;Release();GM.CollectedWorldIds.Add("horse-owned:"+breed);GM.CollectedWorldIds.Add("horse-skill:"+breed);Select(breed);if(personal)Destroy(personal.gameObject);personal=Spawn(breed,at);old.gameObject.SetActive(false);GM.MarkProgressDirty();GM.SaveAdventure();GM.ShowBanner("TAMED • "+Breeds[breed].Name+" • Handling skill improved");return;}}else Mistakes++;if(Mistakes>=3){Fail();return;}Cue();}
  public void Cancel(){if(Target)Fail();}
  void Release(){if(Target){var m=Target.GetComponentInChildren<OpenWorldImportedModel>();if(m)m.State="idle";}if(restrained)restrained.enabled=true;restrained=null;Target=null;}
  void Fail(){var horse=Target;Release();retryAt=Time.unscaledTime+45;if(horse){var wild=horse.GetComponent<OpenWorldWildlife>();if(wild)wild.Startle(GM.Hero.transform.position);}GM.ShowBanner("The horse breaks away • Give it time before trying again");}
  void Select(int breed){GM.CollectedWorldIds.RemoveWhere(f=>f.StartsWith("horse-active:"));GM.CollectedWorldIds.Add("horse-active:"+breed);}
  public bool Buy(int breed){if(!GM||!GM.Hero||GM.IsModalOpen||GM.Hero.Dead||GM.Hero.IsMounted||Target||breed<0||breed>=3||Vector3.Distance(GM.Hero.transform.position,Ground(Stable))>9)return false;bool owned=GM.CollectedWorldIds.Contains("horse-owned:"+breed);if(!owned&&GM.Gold<Breeds[breed].Price){GM.ShowBanner("Not enough gold for this horse");return false;}var next=Spawn(breed,Ground(Stable)+Vector3.forward*4);if(!next)return false;if(!owned){GM.Gold-=Breeds[breed].Price;GM.CollectedWorldIds.Add("horse-owned:"+breed);}if(personal)Destroy(personal.gameObject);personal=next;Select(breed);GM.MarkProgressDirty();GM.SaveAdventure();return true;}
  Vector3 Ground(Vector3 p){p.y=GM.ActiveTerrain.SampleHeight(p)+GM.ActiveTerrain.transform.position.y;return p;}
  OpenWorldAnimalInteraction Spawn(int breed,Vector3 at){var prefab=Resources.Load<GameObject>("World/Stables/Horse");if(!prefab)return null;var root=new GameObject("Owned "+Breeds[breed].Name);root.transform.SetParent(GM.WorldRoot,false);root.transform.position=Ground(at);var model=Instantiate(prefab,root.transform);var b=OpenWorldMaterialHelper.ComputeRendererBounds(model.transform);model.transform.localScale*=1.82f/Mathf.Max(.1f,b.size.y);b=OpenWorldMaterialHelper.ComputeRendererBounds(model.transform);model.transform.position+=root.transform.position-new Vector3(b.center.x,b.min.y,b.center.z);var wild=root.AddComponent<OpenWorldWildlife>();wild.Nature=OpenWorldWildlife.Temper.Tame;wild.HomeRadius=4;var horse=OpenWorldAnimalInteraction.Attach(root,"Horse","owned-horse:"+breed);horse.Breed=breed;horse.SpeciesName=Breeds[breed].Name;horse.HorseStamina=Breeds[breed].Stamina;ApplyCoat(horse);return horse;}
  public static void ApplyCoat(OpenWorldAnimalInteraction horse){foreach(var r in horse.GetComponentsInChildren<SkinnedMeshRenderer>()){if(r.name.IndexOf("Saddle",StringComparison.OrdinalIgnoreCase)>=0||r.name.IndexOf("Hair",StringComparison.OrdinalIgnoreCase)>=0)continue;var block=new MaterialPropertyBlock();r.GetPropertyBlock(block);block.SetColor("_BaseColor",Breeds[horse.Breed].Coat);r.SetPropertyBlock(block);}}
  void Update(){if(!GM||!GM.Hero||!GM.ActiveTerrain)return;if(!stall){stall=new GameObject("Verdant stables");stall.transform.SetParent(GM.WorldRoot,false);stall.transform.position=Ground(Stable);OpenWorldMaterialHelper.SpawnModel("Props/Village/rpgpp_lt_awning_standing_01a","Props/Textures/rpgpp_lt_tex_a",stall.transform,Ground(Stable),3.1f,Color.white,true);var board=new GameObject("Stable ledger");board.transform.SetParent(stall.transform,false);board.transform.localPosition=new Vector3(3,0,0);board.transform.localRotation=Quaternion.Euler(0,-90,0);OpenWorldNoticeBoard.Build(board.transform,"VERDANT STABLES","Road Horse • 350 gold\nCourser • 900 gold\nHighlander • 700 gold\n\nTamed horses welcome");}
   if(!personal){for(int i=0;i<3;i++)if(GM.CollectedWorldIds.Contains("horse-active:"+i)&&GM.CollectedWorldIds.Contains("horse-owned:"+i)){personal=Spawn(i,Ground(Stable)+Vector3.forward*4);break;}}
   if(Target){if(GM.Hero.Dead||GM.IsModalOpen||Vector3.Distance(Target.transform.position,GM.Hero.transform.position)>4.5f)Fail();else if(Time.unscaledTime>Deadline)Counter(0);}
  }
  void OnDestroy(){Release();if(instance==this)instance=null;}
 }
}
